import React from 'react';
import { Box, TextField, Button, Typography, Paper } from '@mui/material';
import { reviewCode } from '../services/codeReviewService';

interface CodeEditorProps {
  taskDescription: string;
  onReviewComplete: (review: any) => void;
  onCodeChange: (code: string) => void;
  initialCode: string;
}

export const CodeEditor: React.FC<CodeEditorProps> = ({ 
  taskDescription, 
  onReviewComplete,
  onCodeChange,
  initialCode 
}) => {
  const [code, setCode] = React.useState(initialCode);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    setCode(initialCode);
  }, [initialCode]);

  const handleCodeChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newCode = e.target.value;
    setCode(newCode);
    onCodeChange(newCode);
  };

  const handleSubmit = async () => {
    if (!code.trim()) {
      setError('Пожалуйста, введите код');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const review = await reviewCode(code, taskDescription);
      onReviewComplete(review);
    } catch (error) {
      setError('Ошибка при проверке кода');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ mt: 2 }}>
      <Typography variant="h6" gutterBottom>
        Ваше решение:
      </Typography>
      <TextField
        multiline
        fullWidth
        rows={10}
        value={code}
        onChange={handleCodeChange}
        placeholder="Введите ваш код здесь..."
        sx={{
          '& .MuiInputBase-root': {
            fontFamily: 'monospace',
            fontSize: '14px',
          },
        }}
      />
      {error && (
        <Typography color="error" sx={{ mt: 1 }}>
          {error}
        </Typography>
      )}
      <Button
        variant="contained"
        onClick={handleSubmit}
        disabled={loading}
        sx={{ mt: 2 }}
      >
        {loading ? 'Проверка...' : 'Отправить на проверку'}
      </Button>
    </Box>
  );
};
